using AdvancedMERTools;using CommandSystem.Commands.RemoteAdmin.Dummies;using Exiled.API.Features;using LabApi.Events.Arguments.ServerEvents;using MEC;using Mirror;using PlayerRoles;using ProjectMER.Events.Arguments;using ProjectMER.Features;using ProjectMER.Features.Objects;using SCP1356Main.API.Extensions;using SCP1356Main.API.Schematic.HealthObject;using SCP1356Main.API.Schematic.Radiation;using UnityEngine;using Config = SCP1356Main.Configs.Config;using RoundEndedEventArgs = Exiled.Events.EventArgs.Server.RoundEndedEventArgs;namespace SCP1356Main.API.Schematic.Start{    public class SchematicSetup{    public SchematicObject SCP1356Chamber { get; set; }    public SchematicObject SCP1356 { get; set; }    public GameObject SCP1356ChamberHealth { get; set; }    public RadiationRaycast radiation { get; set; }    private static readonly Config Config = Plugin.Singleton.Config;    public void SubEvents()    {        ProjectMER.Events.Handlers.Schematic.SchematicSpawned += OnSchematicSpawned;        Exiled.Events.Handlers.Map.Generated += OnGenerated;       Exiled.Events.Handlers.Server.RoundStarted += OnRoundStart;        Exiled.Events.Handlers.Server.RoundEnded += OnRoundEnded;    }    public void UnsubEvents()    {        ProjectMER.Events.Handlers.Schematic.SchematicSpawned -= OnSchematicSpawned;        Exiled.Events.Handlers.Map.Generated -= OnGenerated;       Exiled.Events.Handlers.Server.RoundStarted -= OnRoundStart;        Exiled.Events.Handlers.Server.RoundEnded -= OnRoundEnded;    }    private void OnSchematicSpawned(SchematicSpawnedEventArgs ev)    {        Log.Debug(ev.Schematic.name);        if (ev.Schematic.name.Contains(Config.SCP1356ChamberName))        {            foreach (Transform transform in ev.Schematic.GetComponentsInChildren<Transform>())            {                if (transform.name.Contains(Config.SCP1356RootName))                {                    Log.Debug(Config.SCP1356RootName + " found");                    if (ObjectSpawner.TrySpawnSchematic(                            "GameObject",                            transform.position,                            transform.rotation,                            new Vector3(1f, 1f, 1f),                            out SchematicObject gameObject))                    {                        SCP1356 = gameObject;                        radiation = new RadiationRaycast(SCP1356.transform);                        radiation.Start();                        Log.Info("Spawned SCP-1356 at Postion: " + SCP1356.Position);                       // DummyDuck(SCP1356);                        SCP1356.gameObject.AddHealth(Config.SCP1356Health, SimpleDeathType.Explode);                    }                    else                    {                        Log.Warn($"Failed to spawn schematic object SCP 1356, GameObject: {transform.name}.");                    }                }            }        }    }    private void OnRoundStart()    {    }        private void OnGenerated()    {                foreach (Tools.TransformData transformData in Config.SchematicData)        {            Room room = Room.Get(transformData.RoomType);                        var pos = room.WorldPosition(new Vector3(transformData.PosX, transformData.PosY, transformData.PosZ));            var rot = room.Transform.rotation * Quaternion.Euler(new  Vector3(transformData.RotX, transformData.RotY, transformData.RotZ));            var scale = new Vector3(transformData.ScaleX, transformData.ScaleY, transformData.ScaleZ);            if (transformData.SchematicName == Config.SCP1356ChamberName)            {                Plugin.Singleton.BreachAPI.CurrentRoom = transformData.RoomType;            }                        var schem = ObjectSpawner.SpawnSchematic(transformData.SchematicName, pos, rot, scale);            var deathType = transformData.SimpleDeathType ?? SimpleDeathType.None;            var transformName = transformData.Transform ?? "UseSchematicIfHealthEnabled";            if (transformData.HP <= 0)            {                if (transformData.HP == 0)                {                    Log.Info("Spawned Schematic: " +  transformData.SchematicName + " at: " + pos);                    Log.Warn($"HealthObject for: {transformData.SchematicName} failed to Spawn: HP can't be Zero!");                    continue;                }                Log.Info("Spawned Schematic: " +  transformData.SchematicName + " at: " + pos+" and didnt added Health.") ;                continue;            }            if (transformName.Contains("UseSchematicIfHealthEnabled"))            {                schem.gameObject.AddHealth(transformData.HP, deathType);                Log.Info("Spawned Schematic: " +  transformData.SchematicName + " at: " + pos+" and added Health to Complete Schematic") ;                continue;            }            foreach (Transform transform in schem.GetComponentsInChildren<Transform>())            {                if (transform.name.Contains(transformName))                {                    transform.gameObject.AddHealth(transformData.HP, deathType);                    Log.Info("Spawned Schematic: " +  transformData.SchematicName + " at: " + pos +" and added Health to Transform named " + transformName);                }            }        }                foreach (Tools.ObjectSpawnData objectSpawnData in Config.PrefabSpawns)        {            if (NetworkClient.prefabs.TryGetValue(objectSpawnData.ObjectId, out var prefab) && prefab != null)            {                Room room = Room.Get(objectSpawnData.RoomType);                                var pos = new Vector3(objectSpawnData.PosX, objectSpawnData.PosY, objectSpawnData.PosZ);                var rot = room.Transform.rotation * Quaternion.Euler(new  Vector3(objectSpawnData.RotX, objectSpawnData.RotY, objectSpawnData.RotZ));                Tools.SpawnPrefab(room.Transform.TransformPoint(pos), rot, objectSpawnData.ObjectId);                Log.Debug("Spawned Prefab: " +  NetworkClient.prefabs[objectSpawnData.ObjectId].name + "at: " + pos);            }            else            {                Log.Warn("Prefab in Config with ID: " + objectSpawnData.ObjectId + " at Position: " + new Vector3(objectSpawnData.PosX, objectSpawnData.PosY, objectSpawnData.PosZ) + " has an invalid ID!");            }        }        foreach (Tools.RagdollSpawnData ragdollSpawnData in Config.RagdollSpawns)        {            Room room = Room.Get(ragdollSpawnData.RoomType);            var pos = new Vector3(ragdollSpawnData.PosX, ragdollSpawnData.PosY, ragdollSpawnData.PosZ);            var rot = room.Transform.rotation * Quaternion.Euler(new  Vector3(ragdollSpawnData.RotX, ragdollSpawnData.RotY, ragdollSpawnData.RotZ));            Tools.SpawnRagdoll(room.Transform.TransformPoint(pos),rot, ragdollSpawnData.Name, ragdollSpawnData.DeathReason, ragdollSpawnData.RoleTypeId);            Log.Debug("Spawned Ragdoll: " +  ragdollSpawnData.Name + " at: " + pos);        }        foreach (Tools.PickupSpawnData pickupSpawnData in Config.PickupSpawns)        {            Room room = Room.Get(pickupSpawnData.RoomType);            var pos = new Vector3(pickupSpawnData.PosX, pickupSpawnData.PosY, pickupSpawnData.PosZ);            var rot = room.Transform.rotation * Quaternion.Euler(new  Vector3(pickupSpawnData.RotX, pickupSpawnData.RotY, pickupSpawnData.RotZ));            Tools.SpawnPickup(room.Transform.TransformPoint(pos),rot, pickupSpawnData.ItemType);            Log.Debug("Spawned Pickup: " +  pickupSpawnData.ItemType + " at: " + pos);        }    }        private void OnRoundEnded(RoundEndedEventArgs obj)    {            }    public Npc SCP1356DummyNpc { get; set; }    private void DummyDuck(SchematicObject scp1356)    {        if (!Config.SCP1356Dummy)            return;        SCP1356DummyNpc = Npc.Spawn(Config.SCP1356DummyName, Config.SCP1356DummyRole, scp1356.Position);        Timing.CallDelayed(1f, () =>        {            if (SCP1356DummyNpc == null) return;            SCP1356DummyNpc.IsGodModeEnabled = true;            SCP1356DummyNpc.IsNoclipEnabled = true;            SCP1356DummyNpc.Scale = new Vector3(0.1f, 0.1f, 0.1f);            SCP1356DummyNpc.Rotation = scp1356.Rotation;            HidePlayer(SCP1356DummyNpc);        });    }        public static void HidePlayer(Player target)    {        foreach (var ply in Player.List)        {            if (ply.Connection == null) continue;            ply.Connection.Send(new ObjectDestroyMessage            {                netId = target.NetId            });        }    }}}